294	//
295	// The real Windows sandbox spawn path. Replaces std::process::Command::spawn()
296	// for sandboxed runs. Creates a restricted token (DISABLE_MAX_PRIVILEGE), spawns
297	// via CreateProcessAsUserW, and assigns to the C1 Job Object. Also calls C3's
298	// apply_path_policy before spawn and restore_path_policy after child exit.
299	//
300	// Pattern adapted from OpenAI Codex windows-sandbox-rs (token.rs + process.rs).
301	// Simplified for devboule v1: no AppContainer capabilities, no dedicated sandbox
302	// user, no private desktop. Just DISABLE_MAX_PRIVILEGE + Job Object + ACLs.
303	
304	/// A sandboxed child process spawned with a restricted token.
305	pub struct SandboxedChild {
306	    process_handle: HANDLE,
307	    thread_handle: HANDLE,
308	    pub pid: u32,
309	    stdout_read: HANDLE,
310	    stderr_read: HANDLE,
311	    acl_snapshots: Vec<PathAclSnapshot>,
312	    job: HANDLE,
313	}
