315	impl SandboxedChild {
316	    /// Returns the stdout pipe read handle. Wrap with `std::fs::File::from_raw_handle`.
317	    pub fn stdout_handle(&self) -> HANDLE { self.stdout_read }
318	    /// Returns the stderr pipe read handle.
319	    pub fn stderr_handle(&self) -> HANDLE { self.stderr_read }
320	
321	    /// Wait for the child to exit, then restore the filesystem ACLs (C3) and
322	    /// close all handles. Returns the child's exit code.
323	    pub fn wait_and_restore(self) -> Result<i32, String> {
324	        use windows::Win32::System::Threading::{WaitForSingleObject, GetExitCodeProcess, INFINITE};
325	
326	        let exit_code = unsafe {
327	            WaitForSingleObject(self.process_handle, INFINITE);
328	            let mut code: u32 = 0;
329	            GetExitCodeProcess(self.process_handle, &mut code)
330	                .map_err(|e| format!("GetExitCodeProcess failed: {e}"))?;
331	            code as i32
332	        };
333	
334	        // C3: restore the original ACLs.
335	        restore_path_policy(self.acl_snapshots)?;
336	
337	        unsafe {
338	            let _ = CloseHandle(self.process_handle);
339	            let _ = CloseHandle(self.thread_handle);
340	            let _ = CloseHandle(self.stdout_read);
341	            let _ = CloseHandle(self.stderr_read);
342	            // job handle: intentionally NOT closed (KILL_ON_JOB_CLOSE).
343	            // If we closed it here, the child would be killed before we could
344	            // read its exit code. OS frees it when the parent exits.
345	        }
346	        Ok(exit_code)
347	    }
348	}
