350	/// Build a UTF-16 environment block from (KEY, VALUE) pairs.
351	/// Sorted case-insensitively by key (Windows requires this for CreateProcess).
352	/// Double-null terminated.
353	fn make_env_block(env_vars: &[(String, String)]) -> Vec<u16> {
354	    let mut items: Vec<(String, String, String)> = env_vars.iter()
355	        .map(|(k, v)| (k.to_uppercase(), k.clone(), v.clone()))
356	        .collect();
357	    items.sort_by(|a, b| a.0.cmp(&b.0));
358	    let mut w: Vec<u16> = Vec::new();
359	    for (_, k, v) in items {
360	        let entry = format!("{k}={v}");
361	        w.extend(entry.encode_utf16());
362	        w.push(0);
363	    }
364	    w.push(0);
365	    w
366	}
