368	/// Create an anonymous pipe and make the write end inheritable.
369	fn create_pipe() -> Result<(HANDLE, HANDLE), String> {
370	    use windows::Win32::System::Pipes::CreatePipe;
371	    use windows::Win32::Foundation::SetHandleInformation;
372	    let mut read = HANDLE::default();
373	    let mut write = HANDLE::default();
374	    unsafe {
375	        CreatePipe(&mut read, &mut write, None, 0)
376	            .map_err(|e| format!("CreatePipe failed: {e}"))?;
377	        SetHandleInformation(write, 0x2u32, windows::Win32::Foundation::HANDLE_FLAGS(0x2));
378	    }
379	    Ok((read, write))
380	}
