382	/// Open the current process token and create a restricted version
383	/// with DISABLE_MAX_PRIVILEGE (strips all privileges from the token).
384	fn create_restricted_token() -> Result<HANDLE, String> {
385	    use windows::Win32::Security::{CreateRestrictedToken, CREATE_RESTRICTED_TOKEN_FLAGS, TOKEN_DUPLICATE, TOKEN_QUERY, TOKEN_ASSIGN_PRIMARY, TOKEN_ACCESS_MASK};
386	    use windows::Win32::System::Threading::{GetCurrentProcess, OpenProcessToken};
387	
388	    let mut primary_token = HANDLE::default();
389	    unsafe {
390	        OpenProcessToken(
391	            GetCurrentProcess(),
392	            TOKEN_ACCESS_MASK(TOKEN_DUPLICATE.0 | TOKEN_QUERY.0 | TOKEN_ASSIGN_PRIMARY.0),
393	            &mut primary_token,
394	        ).map_err(|e| format!("OpenProcessToken failed: {e}"))?;
395	    }
396	
397	    let mut restricted_token = HANDLE::default();
398	    unsafe {
399	        CreateRestrictedToken(
400	            primary_token,
401	            CREATE_RESTRICTED_TOKEN_FLAGS(0x1), // DISABLE_MAX_PRIVILEGE
402	            None,
403	            None,
404	            None,
405	            &mut restricted_token,
406	        ).map_err(|e| format!("CreateRestrictedToken failed: {e}"))?;
407	    }
408	
409	    unsafe { let _ = CloseHandle(primary_token); }
410	    Ok(restricted_token)
411	}
