413	/// Create a Job Object with kill-on-close + optional memory limit.
414	fn create_job_object(rlimits: &ResourceLimits) -> Result<HANDLE, String> {
415	    let memory_limit: usize = rlimits
416	        .addr_space_bytes
417	        .map(|b| b as usize)
418	        .unwrap_or(usize::MAX);
419	    unsafe {
420	        let job = CreateJobObjectW(None, None)
421	            .map_err(|e| format!("CreateJobObjectW failed: {e}"))?;
422	        let mut info = std::mem::zeroed::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>();
423	        let mut basic = std::mem::zeroed::<JOBOBJECT_BASIC_LIMIT_INFORMATION>();
424	        basic.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
425	        info.BasicLimitInformation = basic;
426	        info.ProcessMemoryLimit = memory_limit;
427	        SetInformationJobObject(
428	            job,
429	            JobObjectExtendedLimitInformation,
430	            &info as *const _ as *const _,
431	            std::mem::size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>() as u32,
432	        ).map_err(|e| format!("SetInformationJobObject failed: {e}"))?;
433	        Ok(job)
434	    }
435	}
