437	/// Spawn a child process with a restricted token, Job Object, and filesystem ACLs.
438	/// This is the C2 broker: it replaces `std::process::Command::spawn()` for Windows
439	/// sandboxed runs.
440	///
441	/// Integrates C1 (Job Object), C2 (restricted token), and C3 (filesystem ACLs).
442	/// After the child exits, call `wait_and_restore()` to restore ACLs + close handles.
443	pub fn spawn_sandboxed(
444	    policy: &SandboxPolicy,
445	    program: &str,
446	    args: &[String],
447	    cwd: &Path,
448	    env_vars: &[(String, String)],
449	) -> Result<SandboxedChild, String> {
450	    use windows::Win32::System::Threading::{
451	        CreateProcessAsUserW, STARTUPINFOW, PROCESS_INFORMATION,
452	        STARTF_USESTDHANDLES, CREATE_NO_WINDOW, CREATE_UNICODE_ENVIRONMENT,
453	    };
454	    use windows::core::{PWSTR, PCWSTR};
455	    use windows::Win32::Foundation::BOOL;
456	
457	    // C3: apply filesystem ACLs before spawn.
458	    let acl_snapshots = apply_path_policy(policy)?;
459	
460	    // C1: create Job Object.
461	    let job = create_job_object(&policy.rlimits)?;
462	
463	    // C2: create restricted token.
464	    let restricted_token = create_restricted_token()?;
465	
466	    // Create pipes for stdout/stderr.
467	    let (stdout_read, stdout_write) = create_pipe()?;
468	    let (stderr_read, stderr_write) = create_pipe()?;
469	
470	    // Build command line: "program arg1 arg2 ..."
471	    let cmdline = if args.is_empty() {
472	        program.to_string()
473	    } else {
474	        format!("{program} {}", args.join(" "))
475	    };
476	    let mut cmdline_wide: Vec<u16> = cmdline.encode_utf16().chain(std::iter::once(0)).collect();
477	
478	    // Build env block.
479	    let env_block = make_env_block(env_vars);
480	
481	    // Build cwd wide string.
482	    let cwd_wide: Vec<u16> = cwd.to_string_lossy()
483	        .encode_utf16()
484	        .chain(std::iter::once(0))
485	        .collect();
486	
487	    // Desktop name — required for restricted tokens to avoid STATUS_DLL_INIT_FAILED.
488	    let mut desktop: Vec<u16> = "winsta0\\default\0".encode_utf16().collect();
489	
490	    // STARTUPINFOW.
491	    let mut si: STARTUPINFOW = unsafe { std::mem::zeroed() };
492	    si.cb = std::mem::size_of::<STARTUPINFOW>() as u32;
493	    si.dwFlags = STARTF_USESTDHANDLES;
494	    si.hStdOutput = stdout_write;
495	    si.hStdError = stderr_write;
496	    si.hStdInput = HANDLE::default();
497	    si.lpDesktop = windows::core::PWSTR(desktop.as_mut_ptr());
498	
499	    let mut pi: PROCESS_INFORMATION = unsafe { std::mem::zeroed() };
500	    let flags = CREATE_NO_WINDOW | CREATE_UNICODE_ENVIRONMENT;
501	
502	    unsafe {
503	        CreateProcessAsUserW(
504	            restricted_token,
505	            PCWSTR::null(),
506	            PWSTR(cmdline_wide.as_mut_ptr()),
507	            None, None,
508	            BOOL(1),
509	            flags,
510	            Some(env_block.as_ptr() as *const _),
511	            PCWSTR(cwd_wide.as_ptr()),
512	            &si,
513	            &mut pi,
514	        ).map_err(|e| format!("CreateProcessAsUserW failed: {e}"))?;
515	    }
516	
517	    // Close write ends of pipes (parent doesn't need them).
518	    // Close the restricted token (child has its own copy).
519	    unsafe {
520	        let _ = CloseHandle(stdout_write);
521	        let _ = CloseHandle(stderr_write);
522	        let _ = CloseHandle(restricted_token);
523	    }
524	
525	    // C1: assign child to Job Object.
526	    unsafe {
527	        AssignProcessToJobObject(job, pi.hProcess)
528	            .map_err(|e| format!("AssignProcessToJobObject failed: {e}"))?;
529	    }
530	
531	    Ok(SandboxedChild {
532	        process_handle: pi.hProcess,
533	        thread_handle: pi.hThread,
534	        pid: pi.dwProcessId,
535	        stdout_read,
536	        stderr_read,
537	        acl_snapshots,
538	        job,
539	    })
540	}
