165	/// Save the current ACL of `path` to a temp file via `icacls /save`.
166	///
167	/// Note: `icacls` ships on all Windows since Vista (not available on Nano Server
168	/// or Docker without the full Windows base image). The binary backup format is
169	/// machine-local — it cannot be transferred cross-machine, but save→restore on
170	/// the same machine works correctly.
171	///
172	/// Note: this function is called via `std::process::Command`, NOT through Git
173	/// Bash. Rust's `Command` uses `CreateProcessW` directly, so the `/save` flag is
174	/// passed as a literal string (Git Bash's `/save` → `C:/Program Files/Git/save`
175	/// path translation does NOT apply).
176	fn save_acl(path: &Path) -> Result<std::path::PathBuf, String> {
177	    let backup = std::env::temp_dir().join(format!(
178	        "devboule_acl_{}_{}",
179	        std::process::id(),
180	        path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or("root".into())
181	    ));
182	    let out = std::process::Command::new("icacls")
183	        .arg(path.as_os_str())
184	        .args(["/save", &backup.to_string_lossy()])
185	        .output()
186	        .map_err(|e| format!("icacls /save spawn failed: {e}"))?;
187	    if !out.status.success() {
188	        return Err(format!(
189	            "icacls /save failed: {}",
190	            String::from_utf8_lossy(&out.stderr)
191	        ));
192	    }
193	    Ok(backup)
194	}
195	
196	/// Add a deny-write ACE for Everyone (S-1-1-0) on `path` via `icacls /deny`.
197	///
198	/// Warning: Everyone (S-1-1-0) includes the current user. This means the Tauri
199	/// app itself will also be blocked from writing to `path` while the deny ACE is
200	/// active. The save/restore pattern in `apply_path_policy` / `restore_path_policy`
201	/// handles this: the deny is applied BEFORE spawn and removed AFTER the child
202	/// exits. The caller must ensure `restore_path_policy` is called even on error.
203	fn deny_write_everyone(path: &Path) -> Result<(), String> {
204	    let out = std::process::Command::new("icacls")
205	        .arg(path.as_os_str())
206	        .args(["/deny", "*S-1-1-0:(W)"])
207	        .output()
208	        .map_err(|e| format!("icacls /deny spawn failed: {e}"))?;
209	    if !out.status.success() {
210	        return Err(format!(
211	            "icacls /deny failed: {}",
212	            String::from_utf8_lossy(&out.stderr)
213	        ));
214	    }
215	    Ok(())
216	}
