218	/// Add an allow-write ACE for Everyone (S-1-1-0) on `path` via `icacls /grant`.
219	fn allow_write_everyone(path: &Path) -> Result<(), String> {
220	    let out = std::process::Command::new("icacls")
221	        .arg(path.as_os_str())
222	        .args(["/grant", "*S-1-1-0:(W)"])
223	        .output()
224	        .map_err(|e| format!("icacls /grant spawn failed: {e}"))?;
225	    if !out.status.success() {
226	        return Err(format!(
227	            "icacls /grant failed: {}",
228	            String::from_utf8_lossy(&out.stderr)
229	        ));
230	    }
231	    Ok(())
232	}
233	
234	/// Restore the original ACL on `path` from a backup file via `icacls /restore`.
235	fn restore_acl(path: &Path, backup_file: &Path) -> Result<(), String> {
236	    let out = std::process::Command::new("icacls")
237	        .arg(path.as_os_str())
238	        .args(["/restore", &backup_file.to_string_lossy()])
239	        .output()
240	        .map_err(|e| format!("icacls /restore spawn failed: {e}"))?;
241	    if !out.status.success() {
242	        return Err(format!(
243	            "icacls /restore failed: {}",
244	            String::from_utf8_lossy(&out.stderr)
245	        ));
246	    }
247	    Ok(())
248	}
249	
250	/// Apply filesystem ACLs derived from `policy` to the paths it references (C3).
251	///
252	/// - `readonly_root`: adds a deny-write ACE for Everyone (S-1-1-0).
253	/// - `writable_paths`: adds an allow-write ACE for Everyone.
254	///
255	/// Uses `icacls` CLI which adds ACEs INCREMENTALLY (preserves existing ACEs —
256	// better than a raw SDDL replace-all-DACL approach for v1).
257	///
258	/// Returns a snapshot of backup files so [`restore_path_policy`] can restore.
259	///
260	/// **Not wired into the spawner**: the broker sub-plan (C2-broker) will call
261	/// this before spawn. `is_enforced()` stays `false` on Windows.
262	pub fn apply_path_policy(policy: &SandboxPolicy) -> Result<Vec<PathAclSnapshot>, String> {
263	    let mut snapshots = Vec::new();
264	
265	    if policy.readonly_root.is_absolute() {
266	        let canon = canonicalize_path(&policy.readonly_root);
267	        let backup = save_acl(&canon)?;
268	        deny_write_everyone(&canon)?;
269	        snapshots.push(PathAclSnapshot { path: canon, backup_file: backup });
270	    }
271	
272	    for wp in &policy.writable_paths {
273	        if wp.is_absolute() {
274	            let canon = canonicalize_path(wp);
275	            let backup = save_acl(&canon)?;
276	            allow_write_everyone(&canon)?;
277	            snapshots.push(PathAclSnapshot { path: canon, backup_file: backup });
278	        }
279	    }
280	
281	    Ok(snapshots)
282	}
283	
284	/// Restore the original ACLs saved by [`apply_path_policy`].
285	pub fn restore_path_policy(snapshots: Vec<PathAclSnapshot>) -> Result<(), String> {
286	    for snap in snapshots {
287	        restore_acl(&snap.path, &snap.backup_file)?;
288	        let _ = std::fs::remove_file(&snap.backup_file);
289	    }
290	    Ok(())
291	}
292	
293	// ─── C2 broker: restricted token + sandboxed spawn ─────────────────────────────
294	//
295	// The real Windows sandbox spawn path. Replaces std::process::Command::spawn()

